		{ "Unholy Power", "spell_shadow_shadowworddominate", 1, 3, 5, "Your demons deal X% more damage.", { }, false },
		{ "Soul Devourer", "spell_shadow_summonfelhunter", 2, 0, 3, "Milestone. Permanently summons a Felhunter. Its bites hit 2 enemies, prioritizing bosses and elites, and deal X% more damage per 1% missing enemy health.\nConsume Magic: Consumes 10% of your highest-ranked DoT's remaining duration, dealing 150% of the consumed damage.\nRules out Soul Link.", { }, true },
		{ "Soul Link", "spell_shadow_gathershadows", 2, 2, 3, "Milestone. Permanently summons a Voidwalker that hits 2 enemies. Gains 3% damage per 1% Damage Reduction and 2% per 1% bonus max health.\nYour Voidwalkers shield you for X% of their damage, up to 25% of your max health.\nRules out Soul Devourer.", { }, true },
		{ "Demonic Echoes", "spell_shadow_possession", 2, 3, 3, "Your demons' attacks have a X% chance to Echo for full damage. This is their only Echo source.", { }, false },
		{ "Master Demonologist", "spell_shadow_shadowpact", 3, 3, 3, "Increases all damage and your demons' critical strike chance by X%.", { }, false },
		{ "Legion Gate", "spell_shadow_ritualofsacrifice", 4, 1, 1, "Milestone. Every 4 sec, summon 3 random lesser demons for 12–16 sec (max 12).\nSuccubi stun Corrupted enemies. Their kills trigger a Death Coil at 50% damage.", { "Death Coil", }, true },
		{ "Demonic Supremacy", "spell_shadow_curseofachimonde", 4, 3, 1, "Your Infernal and Doomguard become permanent. You can no longer summon lesser demons. Maximum one of each.", { }, false },
		{ "Summon Infernal", "spell_shadow_summoninfernal", 5, 0, 3, "Your damaging spells have a 5% chance to summon an Infernal for 15 sec (max 1). Its Meteor stuns enemies on impact, and it burns nearby enemies with Hellfire at X% effectiveness.", { "Hellfire", }, false },
		{ "Summon Doomguard", "spell_shadow_antimagicshell", 5, 3, 3, "Your damaging spells have a 5% chance to summon a Doomguard for 15 sec (max 1). Its Shadow Bolts hit 2 enemies and inherit your upgrades.\nDoom Bringer: Consecutive hits on the same boss or elite deal 20% more damage, up to X%.", { "Shadow Bolt", }, false },
		{ "Pact of the Annihilan", "spell_shadow_unholystrength", 6, 0, 1, "Capstone. Summons a Pit Lord for X sec every 30 sec, reduced by CDR (min 13 sec). Up to 2 active.\nFelseeker inherits your Searing Pain upgrades and deals 25% more damage to its primary target. It hits up to 6 enemies.\nExclusive with Butcher.", { "Searing Pain", }, true },
		{ "Butcher", "ability_warrior_cleave", 6, 2, 1, "Capstone. Summons a Felguard for X sec every 30 sec, reduced by CDR (min 13 sec). Up to 2 active.\nCleaves up to 10 enemies within 15 yd. Every third swing deals double damage. Deals 50% more damage below 30% enemy health.\nExclusive with Pact of the Annihilan.", { "Cleave", }, true },
	} },
	{ spec = "Destruction", t = {
		{ "Improved Shadow Bolt", "spell_shadow_shadowbolt", 0, 1, 5, "Shadow Bolt deals X% more damage.", { "Shadow Bolt", }, false },
		{ "Cataclysm", "spell_fire_windsofwoe", 0, 2, 5, "Your cooldowns recover X% faster.", { }, false },
		{ "Intensity", "spell_fire_lavaspawn", 1, 0, 5, "Soulfire deals X% more damage.", { "Soulfire", }, false },
		{ "Scorched Earth", "spell_fire_immolation", 1, 2, 5, "Your Hellfire deals X% more damage. Each pulse has a Y% chance to slow each enemy it burns by 40% for 3 sec.", { "Hellfire", }, false },
		{ "Shadow Cleave", "spell_shadow_scourgebuild", 2, 1, 1, "Milestone. Shadow Bolt splits: every bolt that lands forks to 2 more enemies for X% of it.", { "Shadow Bolt", }, true },
		{ "Improved Searing Pain", "spell_fire_soulburn", 2, 2, 3, "Searing Pain and Immolate deal X% more damage.", { "Searing Pain", "Immolate", }, false },
		{ "Destructive Reach", "spell_shadow_corpseexplode", 3, 0, 3, "Rain of Fire and Hellfire reach X% farther.", { "Rain of Fire", "Hellfire", }, false },
		{ "Devastation", "spell_fire_flameshock", 3, 2, 5, "Increases your critical strike chance by X%.", { }, false },
		{ "Conflagrate", "spell_fire_fireball", 4, 1, 1, "Milestone. Start every run with Immolate. Shadow Bolt and Searing Pain make Immolated enemies explode for X% of the hit's damage within 6 yd.", { "Searing Pain", "Shadow Bolt", "Immolate", }, true },
		{ "Emberstorm", "spell_fire_selfdestruct", 4, 2, 5, "Fire spells deal X% more damage.", { }, false },
		{ "Ruin", "spell_shadow_shadowwordpain", 5, 0, 3, "Increases your critical strike damage by X%.", { }, false },
		{ "Bane", "spell_shadow_deathpact", 5, 2, 3, "Shadow Bolt and Immolate cooldowns are X% shorter.", { "Shadow Bolt", "Immolate", }, false },
		{ "Rain of Chaos", "spell_shadow_rainoffire", 6, 1, 1, "Capstone. A second Rain of Fire falls on its own every 13 sec, and its burning ground slows what it touches.", { "Rain of Fire", }, true },
	} },
